{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Tiludronate, a poorly absorbed oral drug, has an absolute bioavailability of only 6% (range 2–11%) in healthy volunteers, demonstrating that poor absorption can yield F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danavorexton had poor oral bioavailability and required IV infusion in clinical studies, illustrating that some compounds fail to achieve adequate oral exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Thalidomide, despite slow and possibly dose-dependent absorption, has high oral bioavailability (80–100%) in fasting volunteers, showing that poor solubility does not always preclude high F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Sertraline, which shares the chlorophenylcyclohexyl substructure, has high oral bioavailability (80–95%) in humans, suggesting that this lipophilic motif can be well absorbed when solubility is adequate.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is atovaquone, a highly lipophilic, practically insoluble 1,4-naphthoquinone. Under fasted conditions, dissolution-limited absorption is expected to keep absolute oral bioavailability below 20%. The most transferable evidence is mixed: sertraline and thalidomide show high F but are more soluble/less lipophilic, while tiludronate and danavorexton demonstrate that poor absorption can produce F < 20%. The fasted-state condition and the molecule's very low aqueous solubility favor low bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability data for atovaquone in fasted humans are provided in the evidence set.",
    "All evidence molecules have low Morgan similarity to the query, limiting transferability.",
    "The effect of food versus fasted state on atovaquone absorption is not captured by the retrieved records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

